import{_ as s,o as i,c as a,a2 as t}from"./chunks/framework.vLhlLNVn.js";const c=JSON.parse('{"title":"Werte auswerten (Grafana, VIS, Skripte)","description":"","frontmatter":{"order":4,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/02.anleitungen/04.werte-auswerten.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/anleitungen/werte-auswerten.md","filePath":"de/adapter/sourceanalytix/anleitungen/werte-auswerten.md","lastUpdated":null}'),n={name:"de/adapter/sourceanalytix/anleitungen/werte-auswerten.md"};function r(h,e,l,d,p,k){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="werte-auswerten-grafana-vis-skripte" tabindex="-1">Werte auswerten (Grafana, VIS, Skripte) <a class="header-anchor" href="#werte-auswerten-grafana-vis-skripte" aria-label="Permalink to &quot;Werte auswerten (Grafana, VIS, Skripte)&quot;">​</a></h1><p><a id="evaluate-across-years-adjusting-everything"></a></p><h2 id="wie-werte-ich-werte-uber-mehrere-jahre-aus-ohne-jedes-jahr-alles-anzupassen" tabindex="-1">Wie werte ich Werte über mehrere Jahre aus, ohne jedes Jahr alles anzupassen? <a class="header-anchor" href="#wie-werte-ich-werte-uber-mehrere-jahre-aus-ohne-jedes-jahr-alles-anzupassen" aria-label="Permalink to &quot;Wie werte ich Werte über mehrere Jahre aus, ohne jedes Jahr alles anzupassen?&quot;">​</a></h2><p>Nimm die States unter <code>sourceanalytix.0.&lt;Gerät&gt;.currentYear</code>. Ihre IDs ändern sich nie, auch nicht zum Jahreswechsel. Für Vergleiche über Jahre zeichnest du die Vorperioden mit einem History-Adapter auf oder liest das Archiv unter <code>sourceanalytix.0.&lt;Gerät&gt;.&lt;Jahr&gt;</code>.</p><table tabindex="0"><thead><tr><th>Ordner</th><th>Inhalt</th></tr></thead><tbody><tr><td><code>currentYear.&lt;Kategorie&gt;.01_currentDay</code> bis <code>05_currentYear</code></td><td>laufende Perioden</td></tr><tr><td><code>currentYear.&lt;Kategorie&gt;.01_previousDay</code> bis <code>05_previousYear</code></td><td>abgeschlossene Vorperioden</td></tr><tr><td><code>currentYear.&lt;Kategorie&gt;.weeks</code>, <code>months</code>, <code>quarters</code></td><td>jede Woche, jeder Monat, jedes Quartal dieses Jahres</td></tr><tr><td><code>&lt;Jahr&gt;.&lt;Kategorie&gt;.weeks</code>, <code>months</code>, <code>quarters</code></td><td>Archiv eines Kalenderjahres, jedes Jahr ein neuer Ordner</td></tr></tbody></table><p><code>&lt;Kategorie&gt;</code> ist <code>consumed</code> oder <code>delivered</code>, <code>costs</code> oder <code>earnings</code> und <code>meterReadings</code>.</p><p>Welche Ordner entstehen, legst du in den Instanz-Einstellungen unter „Haupteinstellungen“ fest: „Laufendes Jahr“ für <code>currentYear</code>, „Jahresstatistik“ für das Archiv. Schaltest du eine Option aus, fragt die Seite vorher nach, denn SourceAnalytix löscht dann diese States des laufenden Jahres. Frühere Jahre bleiben.</p><p>Für Langzeit-Diagramme zeichnest du zum Beispiel <code>03_previousMonth</code> und <code>05_previousYear</code> auf. Jeder Wert kommt einmal pro Periode, mit dem Zeitstempel 23:59:59 Uhr am letzten Tag der Periode. Die Wochen eines Jahres liegen im Ordner des Jahres, zu dem die Kalenderwoche gehört.</p><p><strong>Siehe auch:</strong> <a href="#datapoints-use-grafana-influxdb">Datenpunkte für Grafana/InfluxDB</a> · <a href="./../referenz/einstellungen#instance-settings-exist-periods-decimals">Instanz-Einstellungen</a> · <a href="./../referenz/states-und-meldungen#happens-turn-year">Jahreswechsel</a></p><p><a id="datapoints-use-grafana-influxdb"></a></p><h2 id="welche-datenpunkte-nehme-ich-fur-grafana-influxdb" tabindex="-1">Welche Datenpunkte nehme ich für Grafana/InfluxDB? <a class="header-anchor" href="#welche-datenpunkte-nehme-ich-fur-grafana-influxdb" aria-label="Permalink to &quot;Welche Datenpunkte nehme ich für Grafana/InfluxDB?&quot;">​</a></h2><p>Für Balken die Vorperioden unter <code>currentYear.&lt;Kategorie&gt;</code>: <code>01_previousDay</code>, <code>02_previousWeek</code> und <code>03_previousMonth</code>. Sie bekommen genau einen Wert pro Periode, auch bei 0. Für eigene Auswertungen reicht <code>cumulativeReading</code>.</p><table tabindex="0"><thead><tr><th>Diagramm</th><th>State</th></tr></thead><tbody><tr><td>Tagesbalken</td><td><code>01_previousDay</code></td></tr><tr><td>Wochen vergleichen</td><td><code>02_previousWeek</code></td></tr><tr><td>Monate vergleichen</td><td><code>03_previousMonth</code></td></tr><tr><td>Verlauf heute</td><td><code>01_currentDay</code></td></tr><tr><td>alles selbst rechnen</td><td><code>cumulativeReading</code></td></tr></tbody></table><ol><li>Aktiviere im Reiter „Objekte“ bei diesen States die Aufzeichnung deines History-Adapters, als Zahl.</li><li>Zeichne sie in Grafana als Balken ohne weitere Summierung. Jeder Punkt ist schon der Verbrauch der ganzen Periode.</li></ol><p>Der erste Wert kommt nach dem ersten Periodenwechsel, für <code>01_previousDay</code> also nach Mitternacht.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/states-und-meldungen#yesterday-last-week-last-month">Gestern, letzte Woche, letzter Monat</a> · <a href="./../referenz/states-und-meldungen#meter-readings-cumulative">cumulativeReading</a></p><p><a id="visualise-values-vis-flot-habpanel"></a></p><h2 id="wie-visualisiere-ich-die-werte-in-vis-flot-habpanel-und-der-historie" tabindex="-1">Wie visualisiere ich die Werte in VIS, Flot, HabPanel und der Historie? <a class="header-anchor" href="#wie-visualisiere-ich-die-werte-in-vis-flot-habpanel-und-der-historie" aria-label="Permalink to &quot;Wie visualisiere ich die Werte in VIS, Flot, HabPanel und der Historie?&quot;">​</a></h2><p>SourceAnalytix liefert States, keine Diagramme. Für Verläufe zeichnest du States mit einem History-Adapter auf und zeigst sie in Flot, eCharts, Grafana oder einem VIS-Widget. Für Tabellen ohne Datenbank gibt es <code>statisticsJson</code> mit allen Werten des laufenden Jahres.</p><p>Die Vorperioden tragen den Zeitstempel 23:59:59 Uhr am letzten Tag ihrer Periode, auch wenn ein Wechsel nachgeholt wurde. Der Wert von gestern landet in der Historie also bei gestern, und du hast eine Liste der Tageswerte mit Datum.</p><p>Einzelne Werte bindest du direkt, etwa <code>01_currentDay</code> für „Heute“. Mit der Option „Wochentag“ stehen die Tage der laufenden Woche unter <code>currentYear.&lt;Kategorie&gt;.currentWeek</code>.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/states-und-meldungen#json-values-vis">Gibt es ein JSON mit allen Werten?</a> · <a href="./../referenz/states-und-meldungen#week-month-quarter-states-weekdays">States für Wochen, Monate und Wochentage</a></p><p><a id="read-sourceanalytix-values-script"></a></p><h2 id="wie-lese-ich-sourceanalytix-werte-im-skript" tabindex="-1">Wie lese ich SourceAnalytix-Werte im Skript? <a class="header-anchor" href="#wie-lese-ich-sourceanalytix-werte-im-skript" aria-label="Permalink to &quot;Wie lese ich SourceAnalytix-Werte im Skript?&quot;">​</a></h2><p>Mit <code>getState</code>. Jeder Wert ist ein State unter <code>sourceanalytix.0.&lt;Gerät&gt;</code>, wobei <code>&lt;Gerät&gt;</code> die „Technische ID“ aus der Detailansicht der Quelle ist (unter „Für Experten“). Vergangene Jahre liest du, indem du die Jahreszahl in die ID einsetzt.</p><p>Dieser Monat und derselbe Monat im Vorjahr:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> root</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;sourceanalytix.0.strom&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> months</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;01_January&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;02_February&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;03_March&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;04_April&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;05_May&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;06_June&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;07_July&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;08_August&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;09_September&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;10_October&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;11_November&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;12_December&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> now</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Date</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> month</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> months[now.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getMonth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()];</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> thisMonth</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}.currentYear.consumed.03_currentMonth`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).val;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> lastYearId</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}.${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getFullYear</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}.consumed.months.${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">month</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> lastYear</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> existsState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(lastYearId) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(lastYearId).val </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`Dieser Monat: ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">thisMonth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}, im Vorjahr: ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lastYear</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Den Ordner des Vorjahres gibt es nur, wenn damals „Jahresstatistik“ › „Monate“ an war. Für den Vormonat oder das Vorjahr brauchst du kein Datum: <code>03_previousMonth</code> und <code>05_previousYear</code>.</p><p>Alle Technischen IDs mit ihrem Quell-Datenpunkt liefert:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sendTo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sourceanalytix.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;getUsedOutputIds&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {}, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">JSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">stringify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(result)));</span></span></code></pre></div><p>Schreibe nicht in die States von SourceAnalytix, sie werden mit dem nächsten Wert überschrieben. Für Korrekturen gibt es die <a href="./zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Aktionen bei der Quelle</a>.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#name-datapoint-alias-output-id">Was ist die Output-ID?</a> · <a href="./../referenz/states-und-meldungen#sendto-commands-info-states">Befehle per sendTo</a></p>',32)])])}const u=s(n,[["render",r]]);export{c as __pageData,u as default};
